export function portal(node, options = {}) {
  const { target, class: klass } = options

  const portal = document.createElement('div')
  portal.classList.add('Portal')
  if (klass) portal.classList.add(klass)
  portal.append(node)

  let portalTarget
  if (target) portalTarget = document.querySelector(target)
  if (!target) portalTarget = document.body

  portalTarget.append(portal)

  return {
    destroy() {
      portalTarget.removeChild(portal)
    },
  }
}
